// The menu. Source: brief section 3.5 (DoorDash master list, captured Nov 3, 2026).
// Item text is the restaurant's own item names and section notes only. DoorDash's item descriptions
// are AI-generated by DoorDash and several are wrong, so none are used.
// `source: 'grubhub'` marks items found only on the Grubhub menu (Grubhub price shown).
// Normalized from the scrape (see hand-off report): "Casaba, Green Banana or Mango" -> cassava,
// green banana or mangú; "Home Toast" -> home fries; Empanadas shown from $5.50 (the $3.00 base
// plus the required filling); Appetizers section dropped (it repeats Sides at different prices);
// "Eggs with Jam" omitted (probably "Eggs with Ham", confirm).

export type MenuItem = { name: string; price: number; from?: boolean; detail?: string; source?: 'grubhub' };
export type MenuSection = { id: string; title: string; note?: string; items: MenuItem[] };
export type MenuGroup = { id: string; title: string; sections: MenuSection[] };

const i = (name: string, price: number, extra: Partial<MenuItem> = {}): MenuItem => ({ name, price, ...extra });
const gh = { source: 'grubhub' as const };

